import unittest
from taskq.queue import Queue

class TestQueue(unittest.TestCase):
    def setUp(self):
        self.queue = Queue(':memory:')
        self.queue.register('test_handler', self.test_handler)

    def test_handler(self, payload):
        self.assertEqual(payload, {'key': 'value'})

    def test_enqueue(self):
        task_id = self.queue.enqueue('test_handler', {'key': 'value'})
        self.assertIsInstance(task_id, int)

    def test_stats(self):
        self.queue.enqueue('test_handler', {'key': 'value'})
        stats = self.queue.stats()
        self.assertEqual(stats['pending'], 1)

    def test_dead_letters(self):
        self.queue.enqueue('test_handler', {'key': 'value'})
        self.queue.start()
        time.sleep(1)
        dead_letters = self.queue.dead_letters()
        self.assertEqual(len(dead_letters), 1)

if __name__ == '__main__':
    unittest.main()
